Tool response:
Tool: find_deluxe_cabin
Description: Find a deluxe cabin campsite that can accommodate at least N guests.
Parameters:
    {
      "type": "object",
      "properties": {
        "site_type": {
          "type": "string",
          "description": "Type of campsite to search for (must be 'cabin')",
          "title": "Site Type"
        },
        "max_occupancy": {
          "type": "integer",
          "description": "Minimum number of guests the campsite must accommodate",
          "title": "Max Occupancy"
        }
      },
      "required": [
        "site_type",
        "max_occupancy"
      ]
    }

