Tool response:
Tool: create_reservation
Description: Create a new reservation for a guest.
Parameters:
    {
      "type": "object",
      "properties": {
        "user_id": {
          "type": "integer",
          "title": "User Id"
        },
        "campsite_id": {
          "type": "integer",
          "title": "Campsite Id"
        },
        "check_in_date": {
          "type": "string",
          "title": "Check In Date"
        },
        "check_out_date": {
          "type": "string",
          "title": "Check Out Date"
        },
        "num_guests": {
          "type": "integer",
          "title": "Num Guests"
        },
        "discount_code": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Discount Code"
        }
      },
      "required": [
        "user_id",
        "campsite_id",
        "check_in_date",
        "check_out_date",
        "num_guests"
      ]
    }

