Tool response:
Tool: add_rental_to_reservation
Description: Add a rental item to an existing reservation.
Parameters:
    {
      "type": "object",
      "properties": {
        "reservation_id": {
          "type": "integer",
          "title": "Reservation Id"
        },
        "rental_item_id": {
          "type": "integer",
          "title": "Rental Item Id"
        },
        "quantity": {
          "type": "integer",
          "title": "Quantity"
        },
        "start_date": {
          "type": "string",
          "title": "Start Date"
        },
        "end_date": {
          "type": "string",
          "title": "End Date"
        }
      },
      "required": [
        "reservation_id",
        "rental_item_id",
        "quantity",
        "start_date",
        "end_date"
      ]
    }
